@Composable
fun AppShell(
    current: AppScreen,
    username: String,
    userRole: String,
    isAdmin: Boolean,
    onNavigate: (AppScreen) -> Unit,
    onLogout: () -> Unit,
    content: @Composable () -> Unit,
) {
