                vm.updateUser(u["id"].str(), real, dept, role); editUser = null
            }) { editUser = null }
    }

    resetUser?.let { u ->
        var pwd by remember { mutableStateOf("") }
        AlertDialog(
            onDismissRequest = { resetUser = null },
