            baseUrl = baseUrl.trim(),
            requestTimeoutMillis = (timeoutSec.toLongOrNull() ?: 120L) * 1000,
        ))
        message = "已保存"
    }

    fun saveAndTest() {
        save()
        testing = true
        scope.launch {
            message = when (val r = AppState.api.checkConnection()) {
                is ApiResult.Ok -> r.data
                is ApiResult.Err -> r.message
            }
            testing = false
        }
    }
}

